-- ============================================================================
-- Skyrim Emporium API - Script MySQL / MariaDB (XAMPP)
-- Equivalente a lo que Hibernate genera con las entidades del backend.
-- Ejecutar en phpMyAdmin (pestaña SQL) o: mysql -u root < skyrimemporium.sql
-- ============================================================================

DROP DATABASE IF EXISTS skyrimemporium;
CREATE DATABASE skyrimemporium CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE skyrimemporium;

-- ---------------------------------------------------------------- usuarios
CREATE TABLE usuarios (
  run               VARCHAR(12)  NOT NULL,
  nombre            VARCHAR(50)  NOT NULL,
  apellidos         VARCHAR(100) NOT NULL,
  correo            VARCHAR(100) NOT NULL,
  contrasena_hash   VARCHAR(255) NOT NULL,
  fecha_nacimiento  DATE         NULL,
  tipo              VARCHAR(20)  NOT NULL,   -- Administrador | Vendedor | Cliente
  region            VARCHAR(100) NULL,
  comuna            VARCHAR(100) NULL,
  direccion         VARCHAR(300) NULL,
  CONSTRAINT pk_usuarios PRIMARY KEY (run),
  CONSTRAINT uk_usuarios_correo UNIQUE (correo)
) ENGINE=InnoDB;

-- -------------------------------------------------------------- categorias
CREATE TABLE categorias (
  id      VARCHAR(140) NOT NULL,             -- gremio::slug-del-titulo
  gremio  VARCHAR(40)  NOT NULL,
  titulo  VARCHAR(80)  NOT NULL,
  CONSTRAINT pk_categorias PRIMARY KEY (id)
) ENGINE=InnoDB;

-- --------------------------------------------------------------- productos
CREATE TABLE productos (
  id                 VARCHAR(255) NOT NULL,  -- ej: alquimia::curar-enfermedad
  codigo             VARCHAR(80)  NULL,
  name               VARCHAR(100) NULL,
  price              INT          NULL,
  description        VARCHAR(500) NULL,
  image              LONGTEXT     NULL,
  stock              INT          NULL,
  gremio             VARCHAR(255) NULL,
  categoria_seccion  VARCHAR(255) NULL,
  stock_critico      INT          NULL,
  version            BIGINT       NULL,      -- @Version (bloqueo optimista)
  CONSTRAINT pk_productos PRIMARY KEY (id),
  CONSTRAINT uk_productos_codigo UNIQUE (codigo),
  INDEX idx_productos_gremio_cat (gremio, categoria_seccion)
) ENGINE=InnoDB;

-- ----------------------------------------------------------------- pedidos
CREATE TABLE pedidos (
  id            BIGINT       NOT NULL AUTO_INCREMENT,
  fecha         DATETIME(6)  NULL,
  unidades      INT          NULL,
  total         BIGINT       NULL,
  cliente       VARCHAR(255) NULL,
  correo        VARCHAR(255) NULL,
  cliente_run   VARCHAR(255) NULL,
  estado        VARCHAR(255) NULL,           -- 'Pagada'
  calle         VARCHAR(255) NULL,
  departamento  VARCHAR(255) NULL,
  region        VARCHAR(255) NULL,
  comuna        VARCHAR(255) NULL,
  indicaciones  VARCHAR(255) NULL,
  CONSTRAINT pk_pedidos PRIMARY KEY (id),
  INDEX idx_pedidos_cliente_run (cliente_run)
) ENGINE=InnoDB;

-- ------------------------------------------------------------ pedido_items
CREATE TABLE pedido_items (
  id_interno   BIGINT       NOT NULL AUTO_INCREMENT,
  pedido_id    BIGINT       NOT NULL,
  producto_id  VARCHAR(255) NOT NULL,
  nombre       VARCHAR(100) NOT NULL,
  cantidad     INT          NOT NULL,
  precio       INT          NOT NULL,
  total        BIGINT       NOT NULL,
  CONSTRAINT pk_pedido_items PRIMARY KEY (id_interno),
  CONSTRAINT fk_items_pedido FOREIGN KEY (pedido_id) REFERENCES pedidos(id)
) ENGINE=InnoDB;

